void format_connection_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char ip[INET6_ADDRSTRLEN] = "";
    char port[NI_MAXSERV] = "";
    const char *proto = NULL;

    switch (c->transport_type) {
        case TRANSPORT_TCP:
            proto = "tcp";
            break;
        case TRANSPORT_UDP:
            proto = "udp";
            break;
        default:
            proto = "unknown";
            break;
    }

    if (af == AF_INET || af == AF_INET6) {
        if (sock_addr->sa_family == AF_INET) {
            inet_ntop(AF_INET, &(((struct sockaddr_in *)sock_addr)->sin_addr), ip, INET_ADDRSTRLEN);
            snprintf(port, NI_MAXSERV, "%d",
                     ntohs(((struct sockaddr_in *)sock_addr)->sin_port));
        } else if (sock_addr->sa_family == AF_INET6) {
            inet_ntop(AF_INET6, &(((struct sockaddr_in6 *)sock_addr)->sin6_addr), ip, INET6_ADDRSTRLEN);
            snprintf(port, NI_MAXSERV, "%d",
                     ntohs(((struct sockaddr_in6 *)sock_addr)->sin6_port));
        }
    } else if (af == AF_UNIX) {
        snprintf(ip, sizeof(ip), "%s",
                 ((struct sockaddr_un *)sock_addr)->sun_path);
    }

    if (strlen(ip) == 0) {
        snprintf(ip, sizeof(ip), "[unknown]");
    }

    if (strlen(port) > 0) {
        snprintf(addr, NI_MAXHOST + NI_MAXSERV + 10, "%s.%s:%s", proto, ip, port);
    } else {
        snprintf(addr, NI_MAXHOST + 10, "%s.%s", proto, ip);
    }
}

void format_connection_address(const conn *c, const int af, char *addr, struct sockaddr *sock_addr) {
    char address[NI_MAXHOST] = "";
    char port[NI_MAXSERV] = "";
    const char *proto = "";

    switch (af) {
        case AF_INET:
        case AF_INET6:
            proto = (c->transport == TRANSPORT_TCP) ? "TCP" : "UDP";
            getnameinfo(sock_addr, sizeof(struct sockaddr_in), address, NI_MAXHOST,
                        port, NI_MAXSERV, NI_NUMERICHOST | NI_NUMERICSERV);
            break;
        case AF_UNIX:
            proto = "UNIX";
            strncpy(address, ((struct sockaddr_un *)sock_addr)->sun_path, NI_MAXHOST - 1);
            break;
    }

    if (address[0] == '\0') {
        snprintf(address, sizeof(address), "%s", "[unknown]");
    }

    if (af == AF_INET || af == AF_INET6) {
        snprintf(addr, NI_MAXHOST + sizeof(port) + 10, "%s/%s:%s", proto, address, port);
    } else {
        snprintf(addr, NI_MAXHOST + 10, "%s/%s", proto, address);
    }
}
